changeSet.sql:
CREATE INDEX IF NOT EXISTS idx_book_branch_condition ON book(branch_id, condition);
CREATE INDEX IF NOT EXISTS idx_book_branch_category  ON book(branch_id, category);
CREATE INDEX IF NOT EXISTS idx_book_branch_active    ON book(branch_id, active);
CREATE INDEX IF NOT EXISTS idx_book_registered_at    ON book(branch_id, registered_at DESC);
CREATE INDEX IF NOT EXISTS idx_book_image_order      ON book_image(book_id, "order");
CREATE INDEX IF NOT EXISTS idx_book_stock_book       ON book_stock(book_id, branch_id);

rollback.sql:
DROP INDEX IF EXISTS idx_book_branch_condition;
DROP INDEX IF EXISTS idx_book_branch_category;
DROP INDEX IF EXISTS idx_book_branch_active;
DROP INDEX IF EXISTS idx_book_registered_at;
DROP INDEX IF EXISTS idx_book_image_order;
DROP INDEX IF EXISTS idx_book_stock_book;
